class YsearchDemo < Formula
  desc "Query the public YoloSearch FineWeb benchmark corpus from your terminal"
  homepage "https://yolosearch.teixos.net"
  url "https://git.teixos.net/api/packages/yannick/generic/ysearch-demo-release/v0.3.1/ysearch-demo-v0.3.1-macos-universal.tar.gz"
  version "0.3.1"
  sha256 "066febb5f48c894b8b8ef0e6b2db48d051c3e9bbed12d5952d2dec14bc19032f"

  depends_on :macos

  def install
    bin.install "ysearch-demo"
  end

  def caveats
    # Single-quoted heredoc: Ruby must not read \f as a form feed.
    <<~'EOS'
      ysearch-demo is a client: it holds no search engine. It queries the
      yolosearch-demo container, which needs Apple's container runtime:

        brew install --cask container

      Then just run it. It offers to start the container the first time:

        ysearch-demo

      The corpus is public and read-only, so nothing needs credentials. The
      container caches corpus metadata in ~/.ysearch (about 110 MB), which is
      what makes the second start fast. Deleting it is safe.

        ysearch-demo                    open the query REPL
        ysearch-demo 'text:kubernetes'  run one query
        ysearch-demo serverlog -f       follow the container's output

      In the REPL, \fields lists every field the corpus holds.
    EOS
  end

  test do
    # Runs without a server, which is what a bottle test can check: it catches
    # a broken or wrongly-signed build. Querying would need the container.
    assert_match "ysearch-demo", shell_output("#{bin}/ysearch-demo version")
  end
end
